{
  "decisions": {
    "P0057F0006": {
      "action": "repair",
      "representative_fact_id": "",
      "corrections": [
        {
          "statement": "gpu 벤치마크 모범 사례를 따라 실제 사이클 시간만 측정(가중치 로드 memcpy 등 제외), warm up 한번 수행, CV를 통한 스파이크·분산 규명을 측정 기준으로 세웠다.",
          "limits": "warmup 적용 후에도 측정 시간 및 평균 시간이 오히려 늘어나는 현상이 발생했으며, 스파이크 데이터가 여전히 관찰되었다. warmup 버전이 warmup 이전 버전과 측정 시간에서 큰 차이가 나지 않았고, 스파이크가 없을 때 변동 계수가 더 낮은 경향은 있었으나 원인 규명은 완료되지 않았다.",
          "kind": "method",
          "claim_status": "documented_method",
          "source_origin": "research_note",
          "conditions": ["gpu 벤치마크 모범 사례", "Nvidia warmup 가이드라인 참조"],
          "observations": ["측정 기준 3가지 수립: 실제 사이클 시간만 측정, warm up 한번, CV로 스파이크·분산 규명", "추론·bound 계산·검증 3가지 값을 분리 측정하기로 결정", "warmup 후 시간 증가 및 스파이크 지속 문제 발생", "warmup 유무 간 큰 차이 없음, 스파이크 없을 때 CV가 더 낮은 경향"],
          "parameters": [],
          "measurements": [],
          "element_ids": ["p57:e422", "p57:e423", "p57:e424", "p57:e425", "p57:e426", "p57:e427", "p57:e429", "p57:e430", "p57:e431", "p57:e433", "p57:enh:e4", "p57:enh:e5", "p57:enh:e6", "p57:enh:e7", "p57:enh:e8", "p57:enh:e9", "p57:enh:e10", "p57:enh:e11", "p57:enh:e12", "p57:enh:e14", "p57:enh:e17", "p57:enh:e18"]
        }
      ],
      "reason": "승인 후보 P0057R0F0003은 '적절한 기준을 다시 세우기로 했다'는 결정 부분만 다루며, 대상 사실의 구체적 측정 기준(실제 사이클 시간·warmup·CV), warmup 관련 한계(시간 증가·스파이크 지속·warmup 유무 간 차이·CV 경향), 관찰 내용을 포함하지 않는다. 대상 사실의 statement와 limits는 원문 요소(p57:e422~e433, enh:e4~e18)에서 모두 확인되므로, 승인 후보가 커버하지 못한 나머지 검증 내용을 보존하는 수정 사실을 제안한다. 이전 수리의 numeric_issues는 statement의 'warmup 1회'를 'warm up 한번'으로, limits의 'e434-1/e434-2' 요소 참조를 제거하고 p57:e433 내용으로 직접 서술하여 해소했다. '3가지'는 p57:e424(3개 항목)와 p57:e425('3가지 값')에서 확인되며, '한번'은 p57:e424 'warm up 한번 하기'와 일치한다."
    },
    "P0057R0F0002": {
      "action": "unresolved",
      "representative_fact_id": "",
      "corrections": [],
      "reason": "승인 후보가 없으며, heading '별로 차이가 안난다..'(p57:e419)가 forward/backward bound 계산 시간 차이가 크지 않다는 관찰의 주제문 역할을 한다는 주장은 p57:e420의 '한 0.2ms 정도 차이남'으로 뒷받침되나, heading 자체의 기능(주제문 역할)에 대한 원문 명시적 근거는 부족하다. heading은 단순 감상적 문구이며, 그 기능을 주제문으로 해석하는 것은 연구자의 관찰·해석에 해당한다. 별도 승인 근거가 없어 duplicate로 판단할 수 없고, 수정 가능한 원자 사실로 축소하기도 어려워 unresolved로 둔다."
    },
    "P0057R0F0005": {
      "action": "unresolved",
      "representative_fact_id": "",
      "corrections": [],
      "reason": "승인 후보가 없으며, 측정 기준 3가지(실제 사이클 시간·warmup·CV)에 대한 진술은 p57:e424에서 확인되나, 이 사실만으로는 claim_status=planned의 근거(제출·완료 여부)가 충분히 분리되지 않는다. P0057F0006의 repair에서 해당 내용이 포괄되므로 별도 사실로 유지할 필요가 있는지 재검토가 필요하다. P0057F0006 수리 후 해당 내용이 보존되므로, 중복 방지를 위해 unresolved로 둔다."
    },
    "P0058R0F0003": {
      "action": "repair",
      "representative_fact_id": "",
      "corrections": [
        {
          "statement": "GPU 벤치마크 모범 사례를 따라 NVIDIA의 warm up 가이드라인을 세우고, 실제 사이클 시간만 측정(가중치 로드 memcpy 등 제외), warm up 한번 수행, CV를 통해 스파이크·분산 정도를 규명하며, 추론·bound 계산·검증 3가지 값을 나눠서 측정하기로 했다.",
          "limits": "계획/방법 수립 단계의 내용이며, 실제 측정 수행 결과나 완료 여부는 이 문장만으로 확인되지 않음. warmup 적용 후 시간 증가 및 스파이크 지속 문제는 별도(p57:e426~e433)에서 보고됨.",
          "kind": "method",
          "claim_status": "planned",
          "source_origin": "research_note",
          "conditions": ["GPU 벤치마크 모범 사례 따름", "NVIDIA warm up 가이드라인"],
          "observations": [],
          "parameters": [],
          "measurements": [],
          "element_ids": ["p57:e422", "p57:e423", "p57:e424", "p57:e425", "p57:enh:e4", "p57:enh:e5", "p57:enh:e6", "p57:enh:e7", "p57:enh:e8", "p57:enh:e9", "p57:enh:e10"]
        }
      ],
      "reason": "승인 후보 P0057F0004(추론·bound·검증 분리 측정)와 P0057R0F0004(Nvidia warmup 가이드라인 수립)는 각각 대상 사실의 일부만 다룬다. 대상 사실 statement는 p57:e422~e425 및 enh:e4~e10에서 모두 확인되며, claim_status는 '하기로 했다'는 계획 진술이므로 documented_method보다 planned가 더 적절하다. 이전 수리의 numeric_issues는 statement의 '1) 2) 3)' 번호 매기기와 '1회'를 제거하고, 'warm up 한번 수행'과 '3가지 값'으로 원문(p57:e424 'warm up 한번 하기', p57:e425 '3가지 값')에 맞게 서술하여 해소했다. limits에 warmup 후 문제(p57:e426~e433)가 포함되지 않도록 계획 단계 범위로 명확히 제한한다."
    }
  }
}
